// The Hermes Agent mascot as 1-bit bitmaps (generated by `hermes-gadget face`; see docs/faces.md).
#pragma once

#include <cstdint>
#include <cstdlib>
#include <memory>
#include <string>
#include <string_view>

namespace hg::mascot {

enum class Frame : uint8_t { Idle, Blink, Talk };

// Square, row-major, MSB-first, rows padded to whole bytes. A set bit is ink
// (the white artwork); clear bits are transparent.
struct Bitmap {
  uint16_t size;
  Frame frame;
  const uint8_t* bits;

  bool ink(int x, int y) const {
    const int stride = (size + 7) / 8;
    return (bits[y * stride + (x >> 3)] >> (7 - (x & 7))) & 1;
  }
};

// The largest bitmap of `frame` no bigger than `max_size` (the smallest one
// if none fits).
const Bitmap* pick(int max_size, Frame frame);

// Feature positions in thousandths of the bitmap size, for UI effects.
struct Point {
  int16_t x, y;
};
struct Anchors {
  Point ear_cup;         // headphone cup: "listening" waves start here
  Point mouth;           // "speaking" waves
  Point head_top_right;  // "thinking" dots
  int16_t eyes_y0, eyes_y1;    // rows that change when blinking
  int16_t mouth_y0, mouth_y1;  // rows that change when talking
};
const Anchors& anchors();

// A face Hermes sent for the profile that answers (docs/protocol.md#faces). It has the mascot's
// sizes and frames and replaces it while the app holds one.
struct Face {
  struct Free {
    void operator()(uint8_t* p) const { std::free(p); }
  };
  std::string hash;
  std::unique_ptr<uint8_t, Free> bits;  // every size, smallest first, each as idle, blink, talk
  Anchors anchors;
};
// The face message's `bits`: base64 of the bitmaps, then of the anchors as ten little-endian int16
// in Anchors' field order. False, before allocating anything, when the length is not exactly that;
// false when there is no memory for it, and when an anchor is outside 0..1000 or a row range is
// upside down.
bool parse(std::string_view base64, Face& out);
// pick() and anchors() for `face`, or for the mascot when it is null.
Bitmap pick(int max_size, Frame frame, const Face* face);
const Anchors& anchors(const Face* face);

}  // namespace hg::mascot
